// Parse Task Pack and build minimal context
const data = $input.first();
let text = '';

if (data.binary?.data?.data) {
  text = Buffer.from(data.binary.data.data, 'base64').toString('utf8');
}

// Extract key sections
const sections = {
  raw_content: text,
  task_id: 'T-0001',
  project_root_wsl: $('Set Task Parameters').first().json?.project_root_wsl,
  project_root_win: $('Set Task Parameters').first().json?.project_root_win,
  task_pack_path: $('Set Task Parameters').first().json?.task_pack_path,
  role: $('Set Task Parameters').first().json?.role
};

// Build cursor prompt file
const cursorPrompt = `
# Task Execution Instructions

## Current Role: ${sections.role}

## Task Pack:
${text}

## Execution Rules:
1. Only read files listed in Allowed Inputs
2. Only write to paths listed in Deliverables
3. Follow all constraints strictly
4. Output a receipt in this format:

【完成内容】
- List completed items

【输出文件】
- List created/modified files

【自检】
- [ ] Checklist items verified

【风险与未完成】
- Any risks or incomplete items
`;

return { json: { ...sections, cursor_prompt: cursorPrompt } };

// Check validation results
const validatorOutput = $input.first().json?.stdout || '';
const validatorError = $input.first().json?.stderr || '';
const exitCode = $input.first().json?.exitCode || 0;

const passed = exitCode === 0 && !validatorError.includes('error') && !validatorError.includes('FAIL');

return {
  json: {
    task_id: $('Build Cursor Prompt').first().json?.task_id,
    validation_passed: passed,
    validator_output: validatorOutput,
    validator_error: validatorError,
    status: passed ? 'PENDING_REVIEW' : 'FAILED_VALIDATION'
  }
};
